    """Forward-reachable task set from `failing`: each failing task plus every
    task in any downstream (dependent) WorkGroup. Bounds re-execution so a bad
    upstream task re-runs its dependents, but untouched work is preserved."""
    if not failing or not groups:
        return set(failing)
    task_group, dependents, by_id = _build_dependency_maps(groups)
    return _collect_downstream(failing, task_group, dependents, by_id)


def _build_dependency_maps(groups: list[WorkGroup]) -> tuple[dict[str, str], dict[str, list[str]], dict[str, WorkGroup]]:
    task_group: dict[str, str] = {}
    by_id = {g.id: g for g in groups}
    dependents: dict[str, list[str]] = {g.id: [] for g in groups}
    for g in groups:
        for t in g.tasks:
            task_group[t.id] = g.id
        for d in g.depends_on:
            if d in dependents:
                dependents[d].append(g.id)
    return task_group, dependents, by_id


def _collect_downstream(
    failing: set[str],
    task_group: dict[str, str],
    dependents: dict[str, list[str]],
    by_id: dict[str, WorkGroup],
) -> set[str]:
    out: set[str] = set(failing)
    stack = [task_group[t] for t in failing if t in task_group]
    seen: set[str] = set()
    while stack:
        gid = stack.pop()
        if gid in seen:
            continue
        seen.add(gid)
        out.update(_tasks_in_group(gid, dependents, by_id))
        stack.extend(dependents[gid])
    return out


def _tasks_in_group(gid: str, dependents: dict[str, list[str]], by_id: dict[str, WorkGroup]) -> list[str]:
    return [t.id for t in by_id[gid].tasks]"}
